w3-enterprise-e10.referenceSolution:
select substr(street, 1, position('e' in street)) ||
       replace(substr(street, position('e' in street)+1), 'e','o')
from employees;

w3-enterprise-e11.referenceSolution:
select concat(lower(substr(first_name, 1, 3)), '.', lower(substr(last_name, 1, 3)), '@', lower(d.department_name), '.be') from employees e
join departments d on e.department_id = d.department_id
order by e.first_name;

w3-sa-e19.referenceSolution:
SELECT date_part('months', AGE(
                current_date,
                TO_DATE('01-09-' || TO_CHAR(current_date, 'YYYY'), 'DD-MM-YYYY')
                          )) "Months passed AY";

w4-enterprise-e02.referenceSolution:
select d.department_id, d.manager_id, last_name, salary, parking_spot from departments d
join employees e on d.manager_id = e.employee_id
order by department_id;

w4-enterprise-e05.referenceSolution:
select concat(first_name, ' ', last_name) employee_name, f.name name, f.gender gender, to_char(f.birth_date, 'DD-MM-YYYY') "Date of Birth"   from employees e
join family_members f on f.employee_id = e.employee_id
order by f.birth_date;

w4-enterprise-e07.referenceSolution:
select e1.employee_id, e1.last_name, e1.birth_date from employees e1
join employees e2 on extract(month from e1.birth_date) = extract(month from e2.birth_date) and e1.employee_id != e2.employee_id
order by extract(month from e1.birth_date);

w4-enterprise-e08.referenceSolution:
select pr.project_id, pr.project_name, pr.location, pr.department_id from projects pr
left join projects po on po.project_id = 3
where pr.department_id = po.department_id;

w4-sa-e08.referenceSolution:
select student_id, first_name, last_name from students s
left join zipcodes z on z.zip = s.zip
where z.state = 'CT';

w4-sa-e09.referenceSolution:
select concat(first_name, ' ', last_name) name, section_id, concat(grade_type_code, ' ', grade_code_occurrence) evaluation_type, numeric_grade grade from students s
join grades g on s.student_id = g.student_id
where section_id=87 and concat(first_name, ' ', last_name) = 'Daniel Wicelinski';

w4-sa-e20.referenceSolution:
select distinct s.student_id, s.last_name, s.street_address from students s
join students s2 on s.street_address = s2.street_address and s.zip = s2.zip and s.student_id != s2.student_id
order by  s.street_address;

w4-sa-e21.referenceSolution:
select distinct i.first_name, i.last_name, i.zip from instructors i
join instructors i2 on i.zip = i2.zip and i.instructor_id != i2.instructor_id
order by zip, first_name;

w4-sa-e22.referenceSolution:
select distinct s.section_id, to_char(s.start_date_time, 'DD-MON-YYYY HH24:MI') starttijd, s.location from sections s
join sections s2 on s.start_date_time = s2.start_date_time and s.location = s2.location and s.section_id != s2.section_id
order by starttijd;

w5-enterprise-big-e06.referenceSolution:
select round(avg(hours)) number_of_hours
from tasks
where project_id = 30;

w5-enterprise-big-e08.referenceSolution:
select max(hours) "highest amount hours"
from tasks
where project_id = 20;

w5-enterprise-big-e09.referenceSolution:
select max(birth_date) as youngest_child
from family_members
where  employee_id='999111111' and lower(relationship) in ('daughter', 'son');

w5-enterprise-big-e30.referenceSolution:
select d.department_name, p.project_name, p.location
from departments d
left join projects p on p.department_id = d.department_id;

w5-sa-e04.referenceSolution:
select count(*) "courses without Prerequisites"
from courses
where prerequisite is null;

w5-sa-e08.referenceSolution:
select location, count(*) "Number of sections", sum(capacity) "to capacity", min(capacity) "Minimum capacity", max(capacity) "Maximum capacity"
from sections
group by location;
